mapper.select:
select x.*,a.title article_title,w.word_name,w.acceptation from eng_wrong_word x join eng_article a on a.id=x.article_id join eng_word w on w.id=x.word_id where x.user_id=#{userId}
and x.mastered=#{mastered}
and w.word_name like concat('%',#{wordName},'%')
order by x.update_time desc,x.id desc

mapper.update:
update eng_wrong_word
set wrong_count=#{wrongCount},mastered=#{mastered},update_by=#{updateBy},update_time=now()
where id=#{id} and user_id=#{userId}

update eng_wrong_word
set mastered=1,update_by=#{updateBy},update_time=now()
where user_id=#{userId} and article_id=#{articleId} and word_id=#{wordId}

